package com.fitfinance.controller;
import com.fitfinance.dto.EntryDtos.EntryResponse;import com.fitfinance.entity.Entry;import com.fitfinance.repository.EntryRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final EntryRepository entries;public DashboardController(EntryRepository entries){this.entries=entries;}
 @GetMapping public Map<String,Object> dashboard(Authentication auth){Long uid=(Long)auth.getPrincipal();YearMonth month=YearMonth.now();List<Entry> expenses=entries.findByUserIdAndKindOrderByEntryDateDesc(uid,"expense").stream().filter(e->YearMonth.from(e.getEntryDate()).equals(month)).toList();List<Entry> budgets=entries.findByUserIdAndKindOrderByEntryDateDesc(uid,"budget");List<Entry> workouts=entries.findByUserIdAndKindOrderByEntryDateDesc(uid,"workout").stream().filter(e->YearMonth.from(e.getEntryDate()).equals(month)).toList();List<Entry> goals=entries.findByUserIdAndKindOrderByEntryDateDesc(uid,"goal").stream().filter(e->"ACTIVE".equalsIgnoreCase(e.getStatus())).toList();BigDecimal spent=expenses.stream().map(Entry::getAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal budget=budgets.stream().filter(b->YearMonth.from(b.getEntryDate()).equals(month)).map(Entry::getAmount).filter(Objects::nonNull).findFirst().orElse(BigDecimal.ZERO);Map<String,BigDecimal> totals=new TreeMap<>();expenses.forEach(e->totals.merge(e.getCategory()==null?"OTHER":e.getCategory(),e.getAmount()==null?BigDecimal.ZERO:e.getAmount(),BigDecimal::add));String top=totals.entrySet().stream().max(Map.Entry.comparingByValue()).map(Map.Entry::getKey).orElse(null);double goalProgress=goals.stream().filter(g->g.getTargetValue()!=null&&g.getTargetValue().signum()>0).mapToDouble(g->Math.min(100,g.getCurrentValue()==null?0:g.getCurrentValue().doubleValue()/g.getTargetValue().doubleValue()*100)).average().orElse(0);Map<String,Object> out=new LinkedHashMap<>();out.put("monthlySpending",spent);out.put("monthlyBudget",budget);out.put("budgetUsedPercentage",budget.signum()==0?0:spent.multiply(BigDecimal.valueOf(100)).divide(budget,2,RoundingMode.HALF_UP));out.put("workoutCount",workouts.size());out.put("goalProgressPercentage",goalProgress);out.put("topExpenseCategory",top);out.put("categoryBreakdown",totals.entrySet().stream().map(e->Map.of("category",e.getKey(),"amount",e.getValue())).toList());out.put("recentExpenses",entries.findByUserIdAndKindOrderByEntryDateDesc(uid,"expense").stream().limit(5).map(DashboardController::view).toList());out.put("recentWorkouts",entries.findByUserIdAndKindOrderByEntryDateDesc(uid,"workout").stream().limit(5).map(DashboardController::view).toList());return out;}
 private static EntryResponse view(Entry e){return new EntryResponse(e.getId(),e.getKind(),e.getTitle(),e.getAmount(),e.getCategory(),e.getEntryDate(),e.getDescription(),e.getDurationMinutes(),e.getCaloriesBurned(),e.getWeight(),e.getSteps(),e.getCalories(),e.getTargetValue(),e.getCurrentValue(),e.getUnit(),e.getDeadline(),e.getStatus());}}
